use super::*;
fn prepared()->(EpochFixture,Choices){
 let source=Fixture::new();source.admit();let storage=source.active().unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();
 fs::write(paths.data.join("assistant/conversations.json"),br#"{"version":4,"pets":{"codex":{"id":"second-current","created":3,"updated":4,"messages":[],"session":{"id":"second-native","cwd":"/private-fixture","full_access":false},"tasks":[]}},"archives":{}}"#).unwrap();drop(storage);
 let workspace=portable_workspace(&source);let id=portable(&source,&workspace);let target=Temp::new();let layout=target.layout();for p in [&layout.legacy_config,&layout.legacy_data]{fs::DirBuilder::new().recursive(true).mode(0o700).create(p).unwrap();}let f=EpochFixture{source,target,owner:Harness::new(),workspace,id};let r=f.review(Mode::Fresh).unwrap();let fp=r.fingerprint().unwrap();r.apply(&fp).unwrap();let r=f.review(Mode::Resume).unwrap().authority().unwrap();let fp=r.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();r.apply(&fp).unwrap();let r=f.review(Mode::Resume).unwrap().configuration().unwrap();let fp=r.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();let receipt=r.apply(&fp).unwrap();let mut choice=f.source.choices.clone();choice.inspection_receipt=receipt["receiptHash"].as_str().unwrap().into();choice.main_pet="ai_ollama".into();choice.active_pets.push("ai_ollama".into());(f,choice)
}
fn activation(f:&EpochFixture,c:&Choices)->Result<Activation>{Activation::capture(f.owner.claim(&f.target.layout())?,f.target.layout(),&f.workspace,&f.id,c.clone())}
fn admit(f:&EpochFixture,c:&Choices)->Value{let r=activation(f,c).unwrap();let fp=r.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();r.apply(&fp).unwrap()}
fn active(f:&EpochFixture)->Result<Active>{Active::open(f.owner.claim(&f.target.layout())?,f.target.layout())}
#[test]fn epoch_admission_reuses_c3_originals_and_loads_old_and_current_id_denials_before_storage(){
 let(f,c)=prepared();let root=f.target.layout().config().to_owned();let custody=private_tree_bytes(&root.join(JOB));let before=private_tree_bytes(&root);let r=activation(&f,&c).unwrap();assert!(!r.manifest.changes.is_empty());assert_eq!(r.manifest.version,3);assert_eq!(r.manifest.job().unwrap(),EPOCH_JOB);let v=r.preview().unwrap();assert_eq!(private_tree_bytes(&root),before);assert!(r.apply(&"0".repeat(64)).is_err());assert_eq!(private_tree_bytes(&root),before);let receipt=admit(&f,&c);assert_eq!(receipt["runtimeActivationAvailable"],true);assert_eq!(private_tree_bytes(&root.join(JOB)),custody);assert!(!root.join(EPOCH_JOB).join("originals").exists());let record:Value=serde_json::from_slice(&fs::read(root.join(publication::ADMITTED)).unwrap()).unwrap();assert_eq!(record["version"],3);assert_eq!(record["epoch"]["payloadDepth"],2);
 let storage=active(&f).unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();assert_eq!(paths.config,root.join("payload/payload"));assert_eq!(paths.data,f.target.layout().data().join("payload/payload"));let history=storage.restored_history().unwrap().unwrap();for cid in ["old-current","second-current"]{assert!(history.conversation_allowed("codex",cid,None).is_err());}for sid in ["old-native","second-native"]{assert!(history.native_session_allowed("codex",sid).is_err());}assert!(history.conversation_allowed("codex","fresh-independent",Some("fresh-native")).is_ok());assert!(history.conversation_allowed("ollama","old-current",None).is_ok());assert!(storage.feature_pending("voice").unwrap());assert!(storage.feature_pending("autostart").unwrap());assert!(storage.feature_pending("mobile").unwrap());let settings=crate::settings::read_initialized(&paths.config.join("settings.json")).unwrap();assert_eq!(settings.main_pill,"ai_ollama");assert_eq!(settings.chat_models["lmstudio"],"explicit-free-fixture");assert_eq!(settings.lmstudio_url,"http://127.0.0.1:11444");assert!(!settings.autostart&&!settings.phone_link&&!settings.cli_full_access);assert!(root.join(EPOCH_JOB).join(OPENED).is_file());assert_eq!(private_tree_bytes(&root.join(JOB)),custody);
}
#[test]fn each_epoch_initialization_boundary_requires_exact_review_and_resumes_without_recopying_originals(){
 for cut in [Step::OriginalsReady,Step::Staged(0),Step::Changed(0),Step::BeforeAdmission,Step::Admitted]{let(f,c)=prepared();let root=f.target.layout().config().to_owned();let custody=private_tree_bytes(&root.join(JOB));let r=activation(&f,&c).unwrap();let fp=r.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();assert!(r.apply_using(&fp,|s|if s==cut{Err(Error::Unavailable)}else{Ok(())}).is_err());assert_eq!(private_tree_bytes(&root.join(JOB)),custody);if cut!=Step::Admitted{assert!(active(&f).is_err());}let r=activation(&f,&c).unwrap();let fp=r.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();r.apply(&fp).unwrap();assert!(active(&f).is_ok());assert_eq!(private_tree_bytes(&root.join(JOB)),custody);let before=private_tree_bytes(&root);let r=activation(&f,&c).unwrap();let fp=r.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();r.apply(&fp).unwrap();assert_eq!(private_tree_bytes(&root),before);}
}
#[test]fn changed_epoch_plan_claim_settings_or_custody_never_publish_an_admission(){
 for mode in ["choice","claim","settings","custody"]{let(f,c)=prepared();let r=activation(&f,&c).unwrap();let fp=r.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();if mode=="choice"{drop(r);let mut other=c.clone();other.main_pet="ai_lmstudio".into();assert!(activation(&f,&other).unwrap().apply(&fp).is_err());}else{match mode{"claim"=>f.owner.release(),"settings"=>fs::write(f.target.layout().config().join("payload/payload/settings.json"),b"changed typed target").unwrap(),_=>fs::write(f.target.layout().config().join(JOB).join(READY),b"changed custody").unwrap()};assert!(r.apply(&fp).is_err());}assert!(!f.target.layout().config().join(publication::ADMITTED).exists());}
}
#[test]fn epoch_storage_fences_changed_hmac_ancestor_custody_and_reference_index_without_regranting(){
 for mode in ["ancestor","custody","index"]{let(f,c)=prepared();admit(&f,&c);let root=f.target.layout().config().to_owned();let storage=active(&f).unwrap().into_storage().unwrap();let path=match mode{"ancestor"=>{let body:Value=serde_json::from_slice(&fs::read(epoch_consent(&f).join(".restored-history.json")).unwrap()).unwrap();epoch_consent(&f).join(format!(".restored-history-prior-{}.json",body["body"]["parent"].as_str().unwrap()))},"custody"=>root.join(JOB).join(MANIFEST),_=>root.join(EPOCH_JOB).join(HISTORY)};let original=fs::read(&path).unwrap();fs::write(&path,b"private changed bound metadata").unwrap();assert!(storage.paths().is_err());fs::write(&path,original).unwrap();assert!(storage.paths().is_err());assert!(storage.restored_history().is_err());}
}
#[test]fn epoch_admission_needs_own_seal_and_cannot_reclassify_legacy_or_unknown_job_paths(){
 let(f,c)=prepared();admit(&f,&c);let root=f.target.layout().config().to_owned();let seal=root.join(EPOCH_JOB).join(SEALED);fs::remove_file(&seal).unwrap();assert!(active(&f).is_err());assert!(publication::recover_complete(f.owner.claim(&f.target.layout()).unwrap(),f.target.layout()).is_err());
 let f=Fixture::new();f.admit();fs::DirBuilder::new().mode(0o700).create(f.config().join(EPOCH_JOB)).unwrap();assert!(f.active().is_err());let(f,_)=prepared();fs::DirBuilder::new().mode(0o700).create(f.target.layout().config().join(".restore-admission-unknown")).unwrap();assert!(f.review(Mode::Activation).is_err());
}
#[test]fn native_epoch_ack_is_self_contained_after_new_work_and_archive_removal(){
 let(f,c)=prepared();let first=admit(&f,&c);let storage=active(&f).unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();f.target.file(&paths.data.join("assistant/new-after-epoch-admission.bin"),b"new current work must survive ACK");drop(storage);fs::rename(&f.workspace,f.workspace.with_extension("offline")).unwrap();let choices=f.target.0.join("native-choices3.json");f.target.file(&choices,&c.canonical().unwrap());let args=|approved:Option<&str>|{let mut a=vec!["coucou".into(),"--pets-profile-restore-activate".into(),f.workspace.to_string_lossy().into_owned(),f.id.clone(),"--plan".into(),choices.to_string_lossy().into_owned()];if let Some(fp)=approved{a.extend(["--approve".into(),fp.into()]);}crate::pet_data::restore_cli::parse(&a).unwrap().unwrap()};f.owner.release();let preview=crate::pet_data::restore_cli::execute(args(None),f.owner.address(),"fr.louisraille.coucou",f.target.layout()).unwrap();assert_eq!(preview["status"],"restoredActivationAlreadyAdmitted");let before=private_tree_bytes(f.target.layout().config());let result=crate::pet_data::restore_cli::execute(args(preview["fingerprint"].as_str()),f.owner.address(),"fr.louisraille.coucou",f.target.layout()).unwrap();assert_eq!(result,first);assert_eq!(private_tree_bytes(f.target.layout().config()),before);assert_eq!(fs::read(paths.data.join("assistant/new-after-epoch-admission.bin")).unwrap(),b"new current work must survive ACK");
}
#[test]fn epoch_runtime_backup_uses_complete_restored_root_format2_without_granting_activation(){
 let(f,c)=prepared();admit(&f,&c);let workspace=f.target.0.join("backup3");fs::DirBuilder::new().mode(0o700).create(&workspace).unwrap();let r=current_profile::Review::capture(active(&f).unwrap(),&workspace).unwrap();let v=r.preview().unwrap();assert_eq!(v["archiveVersion"],2);assert_eq!(v["sourcePayloadDepth"],2);assert_eq!(v["dataRestorationAvailable"],true);assert_eq!(v["runtimeActivationAvailable"],false);assert_eq!(fs::read_dir(&workspace).unwrap().count(),0);assert!(r.copy(&"0".repeat(64)).is_err());assert_eq!(fs::read_dir(&workspace).unwrap().count(),0);assert!(active(&f).is_ok());
}
